class Search_Tweets(API_base):
    """
    Search for tweets on Twitter
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_q", "p_cursor", "p_count", "p_tweet_search_mode", "p_result_filter"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_q = params.get('p_q', None)
        if p_q is None:
            return self.handle_error(f"Required parameter 'p_q' is missing", 400)
        is_valid, error = self.validate_type(p_q, 'p_q', str)
        if not is_valid:
            return error
        
        p_cursor = params.get('p_cursor', "")
        if p_cursor is not None:
            is_valid, error = self.validate_type(p_cursor, 'p_cursor', str)
            if not is_valid:
                return error
        
        _default_p_count = int(20) if 20 !=  ""  else 0
        p_count = params.get('p_count', _default_p_count)
        if p_count is not None:
            is_valid, error = self.validate_type(p_count, 'p_count', int)
            if not is_valid:
                return error
        
        p_tweet_search_mode = params.get('p_tweet_search_mode', "popular")
        if p_tweet_search_mode is not None:
            is_valid, error = self.validate_type(p_tweet_search_mode, 'p_tweet_search_mode', str)
            if not is_valid:
                return error
        
        if p_tweet_search_mode is not None and p_tweet_search_mode not in ["popular", "latest"]:
            return self.handle_error(f"Parameter 'p_tweet_search_mode' not in valid enum", 400)
        
        p_result_filter = params.get('p_result_filter', "")
        if p_result_filter is not None:
            is_valid, error = self.validate_type(p_result_filter, 'p_result_filter', str)
            if not is_valid:
                return error
        
        if p_result_filter is not None and p_result_filter not in [""]:
            return self.handle_error(f"Parameter 'p_result_filter' not in valid enum", 400)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Search_Tweets",
                "p_q": p_q,
                "p_cursor": p_cursor,
                "p_count": p_count,
                "p_tweet_search_mode": p_tweet_search_mode,
                "p_result_filter": p_result_filter
            }
        }

