class Moving_Average_MA(API_base):
    """
    Calculates the moving average of a financial instrument's price data.
    """
    def __init__(self):
        pass

    def execute(self, **params):
        expected_params = set(["p_interval", "p_symbol", "p_time_period", "p_outputsize", "p_ma_type", "p_series_type", "p_format"])
        unexpected_params = set(params.keys()) - expected_params 
        if unexpected_params:
            return self.handle_error(f"Unexpected parameters: {', '.join(unexpected_params)}", 400)
        p_interval = params.get('p_interval', None)
        if p_interval is None:
            return self.handle_error(f"Required parameter 'p_interval' is missing", 400)
        is_valid, error = self.validate_type(p_interval, 'p_interval', str)
        if not is_valid:
            return error
        
        if p_interval is not None and p_interval not in ["1min", "5min", "15min", "30min", "45min", "1h", "2h", "4h", "1day", "1week", "1month"]:
            return self.handle_error(f"Parameter 'p_interval' not in valid enum", 400)
        
        p_symbol = params.get('p_symbol', None)
        if p_symbol is None:
            return self.handle_error(f"Required parameter 'p_symbol' is missing", 400)
        is_valid, error = self.validate_type(p_symbol, 'p_symbol', str)
        if not is_valid:
            return error
        
        _default_p_time_period = float(9.0) if 9.0 != "" else 0.0
        p_time_period = params.get('p_time_period', _default_p_time_period)
        if p_time_period is not None:
            is_valid, error = self.validate_type(p_time_period, 'p_time_period', (float, int))
            if not is_valid:
                return error
        if p_time_period is not None:
            p_time_period = float(p_time_period)
        
        _default_p_outputsize = float(9.0) if 9.0 != "" else 0.0
        p_outputsize = params.get('p_outputsize', _default_p_outputsize)
        if p_outputsize is not None:
            is_valid, error = self.validate_type(p_outputsize, 'p_outputsize', (float, int))
            if not is_valid:
                return error
        if p_outputsize is not None:
            p_outputsize = float(p_outputsize)
        
        p_ma_type = params.get('p_ma_type', None)
        if p_ma_type is not None:
            is_valid, error = self.validate_type(p_ma_type, 'p_ma_type', str)
            if not is_valid:
                return error
        
        if p_ma_type is not None and p_ma_type not in ["SMA", "EMA", "WMA", "DEMA", "TEMA", "TRIMA", "KAMA", "MAMA", "T3MA"]:
            return self.handle_error(f"Parameter 'p_ma_type' not in valid enum", 400)
        
        p_series_type = params.get('p_series_type', None)
        if p_series_type is not None:
            is_valid, error = self.validate_type(p_series_type, 'p_series_type', str)
            if not is_valid:
                return error
        
        if p_series_type is not None and p_series_type not in ["open", "high", "low", "close"]:
            return self.handle_error(f"Parameter 'p_series_type' not in valid enum", 400)
        
        p_format = params.get('p_format', "JSON")
        if p_format is not None:
            is_valid, error = self.validate_type(p_format, 'p_format', str)
            if not is_valid:
                return error
        
        if p_format is not None and p_format not in ["CSV", "JSON"]:
            return self.handle_error(f"Parameter 'p_format' not in valid enum", 400)
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Moving_Average_MA",
                "p_interval": p_interval,
                "p_symbol": p_symbol,
                "p_time_period": p_time_period,
                "p_outputsize": p_outputsize,
                "p_ma_type": p_ma_type,
                "p_series_type": p_series_type,
                "p_format": p_format
            }
        }

