        p_subreddit = params.get('p_subreddit', "askreddit")
        if p_subreddit is not None:
            is_valid, error = self.validate_type(p_subreddit, 'p_subreddit', str)
            if not is_valid:
                return error
        
        p_nsfw = params.get('p_nsfw', False)
        if p_nsfw is not None:
            is_valid, error = self.validate_type(p_nsfw, 'p_nsfw', bool)
            if not is_valid:
                return error
        
        p_time = params.get('p_time', "all")
        if p_time is not None:
            is_valid, error = self.validate_type(p_time, 'p_time', str)
            if not is_valid:
                return error
        
        if p_time is not None and p_time not in ["all", "year", "month", "week", "day", "hour"]:
            return self.handle_error(f"Parameter 'p_time' not in valid enum", 400)
        
        p_full_data = params.get('p_full_data', False)
        if p_full_data is not None:
            is_valid, error = self.validate_type(p_full_data, 'p_full_data', bool)
            if not is_valid:
                return error
        
        p_proxy = params.get('p_proxy', "")
        if p_proxy is not None:
            is_valid, error = self.validate_type(p_proxy, 'p_proxy', str)
            if not is_valid:
                return error
        
        p_sort = params.get('p_sort', "hot")
        if p_sort is not None:
            is_valid, error = self.validate_type(p_sort, 'p_sort', str)
            if not is_valid:
                return error
        
        if p_sort is not None and p_sort not in ["relevance", "hot", "top", "new"]:
            return self.handle_error(f"Parameter 'p_sort' not in valid enum", 400)
        
        _default_p_limit = int(10) if 10 !=  ""  else 0
        p_limit = params.get('p_limit', _default_p_limit)
        if p_limit is not None:
            is_valid, error = self.validate_type(p_limit, 'p_limit', int)
            if not is_valid:
                return error
        
        return {
            "status_code": 200, 
            "results": {
                "function_name": "Get_Posts_from_Subreddit",
                "p_get_subreddit_posts": p_get_subreddit_posts,
                "p_subreddit": p_subreddit,
                "p_nsfw": p_nsfw,
                "p_time": p_time,
                "p_full_data": p_full_data,
                "p_proxy": p_proxy,
                "p_sort": p_sort,
                "p_limit": p_limit
            }
        }

